"""Write Postfix's configuration from tidegate.toml at container start. Edit the TOML file, not the generated files."""
from __future__ import annotations

import os
import sys

from . import config

MAIN_CF = """\
# Generated by Tidegate at container start from /etc/tidegate/tidegate.toml. Changes here are overwritten.
compatibility_level = 3.6
myhostname = {hostname}
myorigin = $myhostname
mydestination = localhost
local_transport = error:5.1.1 local delivery is off on this gateway
alias_maps =
alias_database =
inet_interfaces = all
inet_protocols = ipv4
mynetworks = 127.0.0.0/8{trusted}
relay_domains = {relay_domains}
transport_maps = texthash:/etc/postfix/tidegate/transport
{relay_recipient_maps}default_transport = {default_transport}
content_filter = tidegate:filter
tidegate_destination_recipient_limit = 1
soft_bounce = {soft_bounce}
smtpd_banner = $myhostname ESMTP
smtpd_helo_required = yes
disable_vrfy_command = yes
# Port 25 takes mail only for the domains above. An MTA in front (xforward_hosts) is trusted: Tidegate never refuses
# its mail for those domains, so a refusal can't push mail around the filter.
smtpd_relay_restrictions = reject_unauth_destination
smtpd_recipient_restrictions = permit_mynetworks, reject_non_fqdn_recipient
smtpd_sender_restrictions = permit_mynetworks, reject_non_fqdn_sender
smtpd_authorized_xclient_hosts = {xclient}
smtpd_authorized_xforward_hosts = {xforward}
message_size_limit = {size}
smtpd_tls_cert_file = {cert}
smtpd_tls_key_file = {key}
smtpd_tls_security_level = may
smtpd_tls_loglevel = 1
smtpd_tls_received_header = yes
smtp_tls_security_level = may
smtp_tls_loglevel = 1
smtp_tls_CAfile = /etc/ssl/certs/ca-certificates.crt
queue_run_delay = 60s
minimal_backoff_time = 60s
maximal_backoff_time = 600s
maillog_file = /dev/stdout
biff = no
append_dot_mydomain = no
readme_directory = no
smtputf8_enable = yes
notify_classes = resource, software
"""

MASTER_CF = """\
# Generated by Tidegate at container start. Changes here are overwritten.
smtp      inet  n       -       n       -       -       smtpd
pickup    unix  n       -       n       60      1       pickup
  -o content_filter=
  -o receive_override_options=no_header_body_checks
cleanup   unix  n       -       n       -       0       cleanup
qmgr      unix  n       -       n       300     1       qmgr
tlsmgr    unix  -       -       n       1000?   1       tlsmgr
rewrite   unix  -       -       n       -       -       trivial-rewrite
bounce    unix  -       -       n       -       0       bounce
defer     unix  -       -       n       -       0       bounce
trace     unix  -       -       n       -       0       bounce
verify    unix  -       -       n       -       1       verify
flush     unix  n       -       n       1000?   0       flush
proxymap  unix  -       -       n       -       -       proxymap
proxywrite unix -       -       n       -       1       proxymap
smtp      unix  -       -       n       -       -       smtp
relay     unix  -       -       n       -       -       smtp
showq     unix  n       -       n       -       -       showq
error     unix  -       -       n       -       -       error
retry     unix  -       -       n       -       -       error
discard   unix  -       -       n       -       -       discard
local     unix  -       n       n       -       -       local
lmtp      unix  -       -       n       -       -       lmtp
anvil     unix  -       -       n       -       1       anvil
scache    unix  -       -       n       -       1       scache
postlog   unix-dgram n  -       n       -       1       postlogd
# The filter: Postfix hands each message to Tidegate, one recipient at a time.
tidegate  unix  -       n       n       -       {procs}       pipe
  flags=q user=tidegate null_sender=
  argv=/usr/local/bin/tidegate-filter --sender=${{sender}} --recipient=${{recipient}} --client-address=${{client_address}} --client-helo=${{client_helo}} --client-hostname=${{client_hostname}} --queue-id=${{queue_id}}
# Re-injection: mail that passed the filter, digests and releases come back here and are delivered unfiltered.
10025     inet  n       -       n       -       -       smtpd
  -o syslog_name=postfix/reinject
  -o content_filter=
  -o receive_override_options=no_unknown_recipient_checks,no_header_body_checks,no_milters,no_address_mappings
  -o smtpd_helo_restrictions=
  -o smtpd_client_restrictions=
  -o smtpd_sender_restrictions=
  -o smtpd_recipient_restrictions=permit_mynetworks,reject
  -o smtpd_relay_restrictions=permit_mynetworks,reject
  -o mynetworks=127.0.0.0/8,{internal}
  -o smtpd_data_restrictions=
  -o smtpd_end_of_data_restrictions=
  -o smtpd_tls_security_level=none
  -o smtpd_authorized_xforward_hosts=127.0.0.0/8
"""


def transport_lines(cfg) -> list[str]:
    lines = []
    for domain in cfg.gateway.domains:
        hop = cfg.gateway.routes.get(domain) or cfg.gateway.next_hop
        lines += [f"{domain} smtp:{hop}", f".{domain} smtp:{hop}"]
    return lines


def render(cfg, out_dir: str = "/etc/postfix") -> None:
    g = cfg.gateway
    os.makedirs(os.path.join(out_dir, "tidegate"), exist_ok=True)
    with open(os.path.join(out_dir, "tidegate", "transport"), "w") as fh:
        fh.write("\n".join(transport_lines(cfg)) + "\n")
    relay_recipient_maps = ""
    if g.valid_recipients:
        with open(os.path.join(out_dir, "tidegate", "relay_recipients"), "w") as fh:
            fh.write("".join(f"{addr.strip().lower()} OK\n" for addr in g.valid_recipients))
        relay_recipient_maps = "relay_recipient_maps = texthash:/etc/postfix/tidegate/relay_recipients\n"
    cert, key = "/certs/fullchain.pem", "/certs/privkey.pem"
    if not (os.path.exists(cert) and os.path.exists(key)):
        cert, key = "/var/lib/tidegate-tls/selfsigned.pem", "/var/lib/tidegate-tls/selfsigned.key"
    main_cf = MAIN_CF.format(
        hostname=g.hostname, trusted="".join(", " + h for h in g.xforward_hosts), relay_domains=", ".join(g.domains), relay_recipient_maps=relay_recipient_maps,
        default_transport="smtp" if g.outbound == "bounces" else "discard:outbound mail is off on this gateway",
        soft_bounce="yes" if g.soft_bounce else "no", xclient=", ".join(g.xclient_hosts),
        xforward=", ".join(g.xforward_hosts), size=int(g.message_size_limit), cert=cert, key=key)
    with open(os.path.join(out_dir, "main.cf"), "w") as fh:
        fh.write(main_cf)
    with open(os.path.join(out_dir, "master.cf"), "w") as fh:
        fh.write(MASTER_CF.format(procs=int(g.filter_processes), internal=g.internal_subnet))


def main() -> None:
    try:
        render(config.load())
    except config.ConfigError as e:
        print(f"tidegate: configuration error: {e}", file=sys.stderr)
        sys.exit(78)


if __name__ == "__main__":
    main()
